&lt;td&gt;promise-based&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;JOI&lt;/td&gt;
&lt;td&gt;joi&lt;/td&gt;
&lt;td&gt;sync&lt;/td&gt;
&lt;td&gt;schema objects&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
